  return name
    .split(/\s+/)
    .map((part) => part[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
}

export function NavUser() {
  const { data: session, isPending } = authClient.useSession();
  const { isMobile } = useSidebar();
  const user = session?.user;

  if (isPending || !user) return null;

