async (page) => {
  await page.setViewportSize({ width: 1280, height: 800 });
  const names = ["Ada Lovelace","Alan Turing","Grace Hopper","Linus Torvalds","Barbara Liskov","Ken Thompson","Dennis Ritchie","Margaret Hamilton","Edsger Dijkstra","Donald Knuth","Frances Allen","John McCarthy"];
  const reqs = names.map((n, i) => { const [g, f] = n.split(" "); return { id: String(i+1), givenName: g, familyName: f, contactEmail: `${g.toLowerCase()}@example.com`, workspaceEmail: null, status: i % 3 ? "verified" : "provisioning", createdAt: new Date(Date.UTC(2026, 9, 15 - i)).toISOString() }; });
  await page.route(/\/api\/review\/requests(\/.*)?$/, (r) => {
    const url = new URL(r.request().url());
    const m = url.pathname.match(/requests\/([^/]+)(\/plan)?$/);
    if (!m) return r.fulfill({ json: { requests: reqs } });
    const q = reqs.find((x) => x.id === m[1]);
    if (m[2]) return r.fulfill({ json: { workspaceEmail: `${q.givenName.toLowerCase()}`, saved: false, unavailable: false, selected: [], groups: [] } });
    return r.fulfill({ json: { request: { ...q, phone: "+49 89 123", connection: "Community volunteer", workspaceEmail: q.givenName.toLowerCase(), workspaceEmailSaved: false, workspaceEmailTaken: false, workspaceDomain: "example.org", rejectionReason: null, status: "verified" } } });
  });
  await page.goto("http://localhost:3100/review");
  await page.getByRole("link", { name: "Ada Lovelace" }).waitFor({ timeout: 60000 });
  await page.screenshot({ path: ".playwright-mcp/list.png" });
  const p1 = await page.getByText(/Page \d of \d/).textContent();
  await page.getByRole("link", { name: "Alan Turing" }).click();
  await page.getByRole("dialog").waitFor();
  await page.getByText("Community volunteer").waitFor();
  await page.keyboard.press("j");
  await page.getByRole("dialog").getByText("Grace Hopper").first().waitFor();
  for (let i = 0; i < 8; i++) await page.getByRole("button", { name: "Next request" }).click();
  const desc = await page.getByRole("dialog").getByText(/Request \d+ of/).textContent();
  await page.screenshot({ path: ".playwright-mcp/sheet.png" });
  await page.getByRole("button", { name: "Close" }).click();
  await page.getByRole("dialog").waitFor({ state: "hidden" });
  const p2 = await page.getByText(/Page \d of \d/).textContent();
  return { p1, desc, p2, url: page.url() };
}

